async ({ workspace: { read, search } }) => {
  const [es, lib] = await Promise.all([
    read("src/workspace/edit-spec.ts", { format: "raw" }),
    search("declare (function|var|const) (console|setTimeout|structuredClone|TextEncoder)|lib: \\[|\"lib\\.|lib\\.es", { path: "src", regex: true, limit: 30, contextLines: 1 }),
  ]);
  return { es: es.content, lib: lib.matches?.map((m: any) => `${m.file}:${m.line}: ${m.text}`) };
}
